        const latchY = Math.min(1.15, beamY - .3), latchX = -.12;
        const latch = box(part, .34, .055, .065, latchX, latchY, 0, 0x604831);
        latch.rotation.z = -.18;
        const tieX = latchX - .12, tieY = latchY + .022;
        // 吊り梁は高さ二十・奥行き十六センチ。紐を梁の中で途切れさせず、
