          const braceX0 = postX + .035, braceX1 = w / 2 - .09;
          const braceBottom = armY - .2, braceTop = armY - .025;
          const run = braceX1 - braceX0, rise = braceTop - braceBottom;
          const length = Math.hypot(run, rise), angle = Math.atan2(rise, run);
