      const boards = Math.max(2, Math.ceil(innerW / .18)), pitch = innerW / boards;
      for (let i = 0; i < boards; i++) hieiRitualTimber(part,
        pitch - .002, panelH, t - .008,
        -innerW / 2 + (i + .5) * pitch, (p.h + footH) / 2, backZ + (t + .008) / 2,
        i % 2 ? 0x59412b : 0x634832);
