          for (const side of [-1, 1]) hieiRitualTimber(part, cleatW, cleatH, p.d - t,
            x + side * (bayW - cleatW) / 2, cy, t / 2, 0x59412b);
          hieiRitualTimber(part, bayW - cleatW * 2, cleatH, cleatW,
            x, cy, -p.d / 2 + t + cleatW / 2, 0x59412b);
