        roll.rotateX(Math.PI / 2); shapes.set('nodaDocumentRoll', roll);
        // 結び紐は巻物へ角材を差さず、紙の外周へ回す。端面の巻き重ねも共通形で表す。
        const band = new THREE.CylinderGeometry(1, 1, 1, 8, 1, true);
