    for (const yy of [.01, h - .01]) box(p, w, .02, .026, 0, yy, 0, 0x32271c);
    for (const x of [-w / 2 + .01, w / 2 - .01]) box(p, .02, h - .04, .026, x, h / 2, 0, 0x32271c);
    // 軸の向きを交互にし、紙蝶番の位置で表裏へ折れるように据える。
