    // 既存の戸厚の面へ納め、二筋の溝と裏桟の和釘を共用する。
    anegawaFrame(g, w, h, 0x503923, S.quality === 'high', null, recessed, bottomRail);
    // 引手は表裏の掘り込み。突出した取っ手で隣の戸を擦らない。
    if (recessed) {
      const cx = (hx0 + hx1) / 2, cy = (hy0 + hy1) / 2;
      box(g, hx1 - hx0, hy1 - hy0, .002, cx, cy, 0, 0x292016);
      // 掘った縁を板の切り口のままにせず、木製の指掛かりの内面で受ける。
      // 薄い底の両側へ続く内壁を設け、表裏・斜めからもくぼみの深さを見せる。
      // 三ミリの縁を穴の内側だけへ納め、戸厚・引き込み・当たりは変えない。
      for (const x of [hx0 + .0015 * unit, hx1 - .0015 * unit])
        box(g, .003 * unit, hy1 - hy0, .025, x, cy, 0, 0x604831, 'sugi');
      for (const y of [hy0 + .0015, hy1 - .0015])
        box(g, .003, hx1 - hx0 - .006 * unit, .025, cx, y, 0, 0x604831, 'sugi').rotation.z = Math.PI / 2;
    }
